import "./api.js";
//#region src/functions_api.ts
const functionsPath = (projectId, branchId) => `/projects/${encodeURIComponent(projectId)}/branches/${encodeURIComponent(branchId)}/functions`;
const listFunctions = async (apiClient, projectId, branchId, { cursor, limit } = {}) => {
	const { data } = await apiClient.request({
		path: functionsPath(projectId, branchId),
		method: "GET",
		query: {
			cursor,
			limit
		},
		secure: true,
		format: "json"
	});
	return {
		functions: data.functions ?? [],
		next: data.pagination?.next
	};
};
const getFunction = async (apiClient, projectId, branchId, slug) => {
	const { data } = await apiClient.request({
		path: `${functionsPath(projectId, branchId)}/${encodeURIComponent(slug)}`,
		method: "GET",
		secure: true,
		format: "json"
	});
	return data.function;
};
const deleteFunction = async (apiClient, projectId, branchId, slug) => {
	await apiClient.request({
		path: `${functionsPath(projectId, branchId)}/${encodeURIComponent(slug)}`,
		method: "DELETE",
		secure: true
	});
};
const createDeployment = async (apiClient, projectId, branchId, slug, params) => {
	const form = new FormData();
	form.append("zip", new Blob([params.zip]), "bundle.zip");
	form.append("runtime", params.runtime);
	if (params.environment) form.append("environment", params.environment);
	await apiClient.request({
		path: `${functionsPath(projectId, branchId)}/${encodeURIComponent(slug)}/deployments`,
		method: "POST",
		type: "multipart/form-data",
		body: form,
		secure: true
	});
};
//#endregion
export { createDeployment, deleteFunction, getFunction, listFunctions };
